    public static function isOemRequired(string $vin): bool {
        // Check if the vehicle has ADAS features that are highly sensitive to optical distortion
        // or if it falls into a safety-critical category defined by company policy.
        return self::hasAdas($vin) || self::isFleetCriticalAsset($vin);
    }

